// This file is generated by AI.

// 文档链接 / 跳转目标的打开动作: 场景脚本进场景选项卡, 其余资源按类别进资源选项卡。
//
// 单独成文件而不放进 monaco.ts: 这里要调用 project.ts 的打开动作, 而 project.ts 已经依赖
// monaco.ts 的 disposeModel, 放在一起会形成循环依赖。

import * as monaco from 'monaco-editor';

import type { FileKind } from '../lib/fileKind';
import { openFile, openResourceFile } from '../project';
import type { ResourceKind } from '../tabs/model';

import { linkTargetOf } from './document-link';

/** 文件类别 -> 资源选项卡类别 (场景与未知类型按文本打开) */
const RESOURCE_KIND: Record<FileKind, ResourceKind> = {
  image: 'image',
  audio: 'audio',
  video: 'video',
  text: 'text',
  scene: 'text',
  other: 'text',
};

/**
 * 注册资源打开动作 (应用级, 只执行一次)。
 *
 * Monaco 的文档链接、转到定义等都会把目标资源交给这里: 处理不了 (非项目内文件) 时返回
 * `false`, 交给 Monaco 的默认行为 (如外链在系统浏览器中打开)。
 */
export function registerLinkOpener(): void {
  monaco.editor.registerEditorOpener({
    openCodeEditor: (_source, resource) => {
      const target = linkTargetOf(resource.toString());
      if (!target) return false;

      const open =
        target.kind === 'scene' ? openFile(target.path) : openResourceFile(target.path, RESOURCE_KIND[target.kind]);
      // 链接可能是过期快照 (文件已被删除 / 改名): 打开失败只记录日志, 不影响编辑器
      void open.catch((error) => console.error('打开资源链接失败', target.path, error));
      return true;
    },
  });
}
